// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        amount = bound(amount, 1, address(this).balance == 0 ? 1 ether : address(this).balance);
        Reverter r = new Reverter();
        vm.deal(address(this), amount);
        vm.prank(address(this));
        bool ok;
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "send to a receiver that reverts must revert the whole call");
    }
}

contract Reverter {
    receive() external payable {
        revert();
    }

    fallback() external payable {
        revert();
    }
}
